using Crateside.Core.Queue;

namespace Crateside.Tests.Queue;

public class PremiumOutlookReaderTests
{
    // The tail of a real auto-generated art track description (Cornelius, Wsk3rBhYqoc).
    private const string ArtTrackDescription = """
        Provided to YouTube by The Orchard Enterprises

        Environmental · Cornelius · Keigo Oyamada

        Dream in Dream

        Released on: 2023-06-28

        Auto-generated by YouTube.
        """;

    [Fact]
    public void An_auto_generated_description_is_an_art_track() =>
        Assert.Equal(
            PremiumOutlook.ArtTrack,
            PremiumOutlookReader.FromDescription(ArtTrackDescription)
        );

    [Fact]
    public void An_ordinary_description_is_a_video_upload() =>
        Assert.Equal(
            PremiumOutlook.VideoUpload,
            PremiumOutlookReader.FromDescription("check out my mix! subscribe for more")
        );

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("   ")]
    public void Nothing_to_judge_by_is_unknown_rather_than_a_guess(string? description) =>
        Assert.Equal(PremiumOutlook.Unknown, PremiumOutlookReader.FromDescription(description));
}

public class QueueBatchTests
{
    private static QueueItem Item(string id, int daysAgo) =>
        new()
        {
            PlaylistItemId = id,
            VideoId = id,
            Title = id,
            AddedAt = new DateTimeOffset(2026, 8, 13, 0, 0, 0, TimeSpan.Zero).AddDays(-daysAgo),
        };

    private static QueueView ViewOf(params QueueItem[] outstanding) =>
        new()
        {
            Items = outstanding,
            Outstanding = outstanding,
            FullyProcessed = [],
            AwaitingKey = [],
            AwaitingSeparation = [],
        };

    [Fact]
    public void The_batch_takes_the_oldest_first()
    {
        var view = ViewOf(Item("oldest", 30), Item("middle", 20), Item("newest", 1));

        Assert.Equal(["oldest", "middle"], view.NextBatch(2).Select(i => i.PlaylistItemId));
    }

    [Fact]
    public void A_pinned_item_joins_the_batch_without_displacing_anything()
    {
        // Pinning a just-added banger must not silently drop the oldest item off the end.
        var view = ViewOf(Item("oldest", 30), Item("middle", 20), Item("newest", 1));

        var batch = view.NextBatch(2, new HashSet<string> { "newest" });

        Assert.Equal(["oldest", "middle", "newest"], batch.Select(i => i.PlaylistItemId));
    }

    [Fact]
    public void Pinning_something_already_in_the_batch_does_not_duplicate_it()
    {
        var view = ViewOf(Item("oldest", 30), Item("newest", 1));

        var batch = view.NextBatch(2, new HashSet<string> { "oldest" });

        Assert.Equal(["oldest", "newest"], batch.Select(i => i.PlaylistItemId));
    }

    [Fact]
    public void A_batch_larger_than_the_queue_is_the_whole_queue()
    {
        var view = ViewOf(Item("a", 2), Item("b", 1));

        Assert.Equal(2, view.NextBatch(20).Count);
    }

    [Fact]
    public void A_zero_batch_still_honours_pins()
    {
        var view = ViewOf(Item("a", 2), Item("b", 1));

        Assert.Equal(
            ["b"],
            view.NextBatch(0, new HashSet<string> { "b" }).Select(i => i.PlaylistItemId)
        );
    }

    [Fact]
    public void A_negative_batch_is_rejected() =>
        Assert.Throws<ArgumentOutOfRangeException>(() => ViewOf().NextBatch(-1));
}
